import * as THREE from 'three';import {GLTFLoader} from './vendor/GLTFLoader.js';import {OrbitControls} from './vendor/OrbitControls.js';import {definitions} from './circuit.mjs';
export async function createTable(container,screenCanvas,callbacks){
 const scene=new THREE.Scene();scene.background=new THREE.Color('#eaf0f3');const renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));container.prepend(renderer.domElement);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.3;
 const camera=new THREE.OrthographicCamera(-65,65,55,-55,.01,1000);camera.up.set(0,1,0);camera.position.set(0,0,200);const controls=new OrbitControls(camera,renderer.domElement);controls.enableRotate=false;controls.enableDamping=true;controls.screenSpacePanning=true;controls.target.set(0,0,0);controls.minZoom=.4;controls.maxZoom=3;controls.mouseButtons={LEFT:null,MIDDLE:THREE.MOUSE.PAN,RIGHT:THREE.MOUSE.ROTATE};
 scene.add(new THREE.HemisphereLight(0xffffff,0x667b8a,3));for(const [x,y,z,power] of [[-40,40,90,4],[40,-20,60,2],[-30,20,-60,2]]){const l=new THREE.DirectionalLight(0xffffff,power);l.position.set(x,y,z);scene.add(l);}
 const grid=new THREE.GridHelper(300,60,0xc6d5de,0xdce5eb);grid.rotation.x=Math.PI/2;grid.position.z=-10;scene.add(grid);
 const roots=new Map(),pins=new Map(),labels=container.querySelector('#labels'),ray=new THREE.Raycaster(),mouse=new THREE.Vector2(),plane=new THREE.Plane(new THREE.Vector3(0,0,1),0);let mode='top',wires=[],wireObjs=[],suggest=[],picked=null,selected=null,drag=null;
 const texture=new THREE.CanvasTexture(screenCanvas);texture.magFilter=THREE.NearestFilter;texture.minFilter=THREE.NearestFilter;texture.colorSpace=THREE.SRGBColorSpace;
 const screen=new THREE.Mesh(new THREE.PlaneGeometry(23,11.5),new THREE.MeshBasicMaterial({map:texture,side:THREE.DoubleSide}));screen.position.set(0,-.1,1.43);
 const loader=new GLTFLoader();
 await Promise.all(definitions.map(async(d)=>{const data=await loader.loadAsync(`./assets/part${d.model}.glb`);const group=new THREE.Group();const model=data.scene;const bounds=new THREE.Box3().setFromObject(model);const expected=d.id==='speaker'?43:d.id==='mic'?15:d.id==='amp'?19:d.id==='esp'?18:27;const scale=expected/(bounds.max.x-bounds.min.x);model.scale.multiplyScalar(scale);model.updateMatrixWorld(true);group.add(model);model.traverse(o=>{if(o.isMesh){o.userData.part=d.id;if(o.material){o.material.metalness=Math.min(o.material.metalness??0,.65);}}});group.userData={id:d.id,flipped:false};group.position.set(...d.pos,0);scene.add(group);roots.set(d.id,group);if(d.id==='oled')group.add(screen);
 const title=document.createElement('div');title.className='partlabel';title.textContent=d.name;labels.append(title);group.userData.title=title;
 for(const [name,x,y] of d.pins){const id=d.id+':'+name;const node=new THREE.Object3D();node.position.set(x,y,1.0);group.add(node);const btn=document.createElement('button');btn.className='pinlabel';btn.textContent=name;btn.title=d.name+' · '+name;btn.setAttribute('aria-label',btn.title);btn.addEventListener('pointerdown',e=>e.stopPropagation());btn.onclick=e=>{e.stopPropagation();callbacks.pin(id);};labels.append(btn);pins.set(id,{node,btn,d,name});}
 }));
 function world(id){return pins.get(id)?.node.getWorldPosition(new THREE.Vector3());}
 function rebuildWires(){for(const o of wireObjs){scene.remove(o);o.geometry.dispose();o.material.dispose();}wireObjs=[];for(const w of wires){const a=world(w.a),b=world(w.b);if(!a||!b)continue;const a1=a.clone().add(new THREE.Vector3(0,0,5)),b1=b.clone().add(new THREE.Vector3(0,0,5));const curve=new THREE.CubicBezierCurve3(a,a1,b1,b);const color=[w.a,w.b].some(x=>/:GND$|:G$/.test(x))?0x273c49:[w.a,w.b].some(x=>/:VCC$|:3.3$|:Vin$|:VDD$/.test(x))?0xe15449:[w.a,w.b].some(x=>/:SCL$/.test(x))?0xe1a32c:0x1499ac;const mesh=new THREE.Mesh(new THREE.TubeGeometry(curve,24,.22,6,false),new THREE.MeshStandardMaterial({color,roughness:.5}));scene.add(mesh);wireObjs.push(mesh);}}
 function resize(){const w=container.clientWidth,h=container.clientHeight;renderer.setSize(w,h,false);const aspect=w/h;const span=aspect<1?95/aspect:100;camera.left=-span*aspect/2;camera.right=span*aspect/2;camera.top=span/2;camera.bottom=-span/2;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(container);resize();
 function project(v){v.project(camera);return[(v.x+1)/2*container.clientWidth,(-v.y+1)/2*container.clientHeight,v.z];}
 function render(){requestAnimationFrame(render);controls.update();for(const d of definitions){const g=roots.get(d.id),label=g.userData.title;label.style.display=g.visible?'':'none';if(g.visible){const [x,y]=project(g.localToWorld(new THREE.Vector3(0,-(d.id==='mic'?11:17),0)));label.style.left=x+'px';label.style.top=y+'px';}}
 // Labels form enlarged pin targets outside the boards; nodes remain at physical pins.
 for(const [id,p] of pins){const g=roots.get(p.d.id),btn=p.btn;btn.style.display=g.visible&&mode==='top'?'':'none';if(!g.visible||mode!=='top')continue;const idx=p.d.pins.findIndex(v=>v[0]===p.name);let v=p.node.position.clone();if(p.d.id==='esp'){v.x=Math.sign(v.x)*14;v.y=12-(idx%8)*3.5;}else if(p.d.id==='oled'){v.x=(idx-1.5)*9;v.y=20+(idx%2)*4;}else if(p.d.id==='amp'&&idx<7){v.x=(idx-3)*5;v.y=-16-(idx%2)*4;}else if(p.d.id==='mic'){v.x=Math.sign(v.x)*12;v.y=(idx%3-1)*5;}else v.y+=5;const[x,y]=project(g.localToWorld(v));btn.style.left=x+'px';btn.style.top=y+'px';btn.classList.toggle('suggest',suggest.includes(id));btn.classList.toggle('picked',id===picked);}
 renderer.render(scene,camera);}render();
 function pointer(e){const r=renderer.domElement.getBoundingClientRect();mouse.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(mouse,camera);}
 renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0)return;pointer(e);const hit=ray.intersectObjects([...roots.values()].filter(g=>g.visible),true).find(x=>x.object.userData.part);if(!hit){selected=null;callbacks.select(null);return;}const id=hit.object.userData.part;selected=id;callbacks.select(id);const p=new THREE.Vector3();if(ray.ray.intersectPlane(plane,p)){drag={id,offset:roots.get(id).position.clone().sub(p),start:[e.clientX,e.clientY]};controls.enabled=false;renderer.domElement.setPointerCapture(e.pointerId);}});
 renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;pointer(e);const p=new THREE.Vector3();if(ray.ray.intersectPlane(plane,p)){const g=roots.get(drag.id);g.position.copy(p.add(drag.offset));g.position.x=THREE.MathUtils.clamp(g.position.x,-100,100);g.position.y=THREE.MathUtils.clamp(g.position.y,-100,100);g.position.z=0;rebuildWires();}});
 const release=()=>{if(drag){drag=null;controls.enabled=true;callbacks.change();}};renderer.domElement.addEventListener('pointerup',release);renderer.domElement.addEventListener('pointercancel',release);
 return{roots,refreshScreen(){texture.needsUpdate=true;},setWires(v){wires=v;rebuildWires();},highlight(ids,from){suggest=ids;picked=from;},select(id){selected=id;callbacks.select(id);},setMode(v){mode=v;controls.enableRotate=v==='three';camera.position.set(v==='three'?55:0,v==='three'?-65:0,v==='three'?95:200);camera.up.set(0,1,0);controls.target.set(0,0,0);controls.update();},center(){camera.zoom=1;camera.updateProjectionMatrix();controls.target.set(0,0,0);camera.position.set(mode==='three'?55:0,mode==='three'?-65:0,mode==='three'?95:200);controls.update();},rotate(){if(selected){roots.get(selected).rotation.z+=Math.PI/2;rebuildWires();callbacks.change();}},flip(){if(selected){const g=roots.get(selected);g.userData.flipped=!g.userData.flipped;g.rotation.y=g.userData.flipped?Math.PI:0;rebuildWires();callbacks.change();}},setActive(id,v){roots.get(id).visible=v;},state(){return [...roots].filter(([,g])=>g.visible).map(([id,g])=>({id,pos:[g.position.x,g.position.y],rotation:g.rotation.z,flipped:g.userData.flipped}));},restore(parts){for(const[id,g]of roots){const p=parts.find(x=>x.id===id);g.visible=!!p;if(p){g.position.set(...p.pos,0);g.rotation.set(0,p.flipped?Math.PI:0,p.rotation);g.userData.flipped=p.flipped;}}rebuildWires();},led(on){const g=roots.get('esp');let bulb=g.getObjectByName('virtual-led');if(!bulb){bulb=new THREE.Mesh(new THREE.SphereGeometry(.55),new THREE.MeshBasicMaterial({color:0x198eff}));bulb.name='virtual-led';bulb.position.set(4.1,1.25,1.6);g.add(bulb);}bulb.visible=on;}};
}
